<script setup>
import DateInput from '../components/DateInput.vue';
import {ref,computed,onUnmounted} from 'vue';import Icon from '../components/Icon.vue';import BaseModal from '../components/BaseModal.vue';import EmptyState from '../components/EmptyState.vue';
import {state,company,api,scope,useResource,rows,notify,ask,changed} from '../lib/workspace';import {money,date,amount,inputMoney,periodDate,uid,normalized,statusLabel} from '../lib/format';
const kind=ref('payable'),query=ref(''),status=ref('open'),show=ref(false),mode=ref('new'),busy=ref(false),error=ref(''),form=ref({}),selected=ref(null),context=ref({});let baseline='';
const {data,loading,error:loadError}=useResource(async()=>{if(!state.companyId)return {titles:[],accounts:[],documents:[]};const[t,a,d]=await Promise.all([api(scope('/titles')),api(scope('/accounts')),api(scope(`/documents?period=${state.period}`))]);return {titles:rows(t),accounts:rows(a),documents:rows(d)};},{titles:[],accounts:[],documents:[]});
const titles=computed(()=>data.value.titles.filter(t=>t.kind===kind.value));const filtered=computed(()=>titles.value.filter(t=>(!status.value||(status.value==='open'?(t.balance_cents>0):t.status===status.value))&&normalized(`${t.description} ${t.partner_name} ${t.document}`).includes(normalized(query.value))));
const balance=computed(()=>titles.value.reduce((s,t)=>s+(t.balance_cents||0),0)),paid=computed(()=>titles.value.reduce((s,t)=>s+(t.paid_cents||0),0));
function open(t=null){mode.value=t?'settle':'new';selected.value=t;context.value={id:state.companyId,name:company.value?.trade_name||company.value?.name,period:state.period};form.value=t?{date:periodDate(state.period),amount:inputMoney(t.balance_cents),reason:'',idempotency_key:uid(),integrate:false,debit_account_id:'',credit_account_id:''}:{kind:kind.value,description:'',partner_name:'',document:'',issue_date:periodDate(state.period),due_date:periodDate(state.period),amount:'',document_id:''};baseline=JSON.stringify(form.value);error.value='';show.value=true;state.editor={name:t?'Baixa financeira':'Título financeiro',companyId:state.companyId};}
async function close(){if(busy.value)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'Os dados desta janela ainda não foram salvos.',confirmLabel:'Descartar',danger:true}))return;show.value=false;state.editor=null;}
async function save(){busy.value=true;error.value='';try{const payload={...form.value,amount:amount(form.value.amount)};if(mode.value==='new'){payload.document_id=payload.document_id?Number(payload.document_id):null;await api(scope('/titles',context.value.id),{method:'POST',body:payload});}else{if(payload.integrate)payload.lines=[{account_id:Number(payload.debit_account_id),debit:payload.amount,credit:'0.00'},{account_id:Number(payload.credit_account_id),debit:'0.00',credit:payload.amount}];await api(scope(`/titles/${selected.value.id}/settle`,context.value.id),{method:'POST',body:payload});}show.value=false;state.editor=null;changed();notify(mode.value==='new'?'Título financeiro cadastrado.':form.value.integrate?'Baixa e lançamento contábil registrados.':'Baixa financeira registrada.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">GESTÃO FINANCEIRA</div><h1>Contas a pagar e receber</h1><p>Controle títulos, vencimentos e baixas vinculados à empresa ativa.</p></div><button class="button primary" @click="open()"><Icon name="plus"/>Novo título</button></header><div class="finance-top"><div class="segmented"><button :class="{selected:kind==='payable'}" @click="kind='payable'"><Icon name="out" :size="16"/>A pagar</button><button :class="{selected:kind==='receivable'}" @click="kind='receivable'"><Icon name="in" :size="16"/>A receber</button></div><div class="mini-metric"><span>Saldo em aberto</span><strong>{{money(balance)}}</strong></div><div class="mini-metric"><span>Baixas registradas</span><strong class="positive">{{money(paid)}}</strong></div></div><div v-if="loadError" class="message error">{{loadError}}</div><section class="panel"><div class="table-toolbar"><div class="search-field"><Icon name="search"/><input v-model="query" placeholder="Pesquisar título, pessoa ou documento" aria-label="Pesquisar títulos"/></div><select v-model="status" aria-label="Filtrar situação financeira"><option value="open">Em aberto e parciais</option><option value="settled">Baixados</option><option value="">Todas as situações</option></select><span class="count">{{filtered.length}} títulos</span></div><div v-if="loading" class="loading-line"><Icon name="loading"/>Carregando títulos...</div><div v-else-if="filtered.length" class="table-scroll"><table><thead><tr><th>Vencimento</th><th>Título / pessoa</th><th>Documento</th><th class="right">Valor original</th><th class="right">Saldo</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="t in filtered" :key="t.id"><td class="nowrap">{{date(t.due_date)}}</td><td><strong>{{t.description}}</strong><small class="cell-secondary">{{t.partner_name||'Não informado'}}</small></td><td class="mono">{{t.document||'—'}}</td><td class="right money">{{money(t.amount_cents)}}</td><td class="right money"><strong>{{money(t.balance_cents)}}</strong></td><td><span class="badge" :class="t.status==='settled'?'success':t.status==='partial'?'warning':'neutral'">{{t.status==='settled'?'Baixado':statusLabel(t.status)}}</span></td><td><button v-if="t.balance_cents>0" class="button small outline" @click="open(t)" :aria-label="`Baixar título ${t.description}`"><Icon name="check" :size="14"/>Baixar</button><span v-else class="subtle"><Icon name="checks" :size="17"/></span></td></tr></tbody></table></div><EmptyState v-else title="Nenhum título neste filtro" text="Cadastre uma obrigação ou recebimento, ou altere o filtro de situação." icon="finance"/><footer class="table-footer"><span>Uma baixa pode ser parcial. A contabilização exige contas explicitamente selecionadas.</span><span>{{filtered.length}} registros</span></footer></section>
<BaseModal v-if="show" :title="mode==='new'?'Novo título financeiro':kind==='payable'?'Registrar pagamento':'Registrar recebimento'" :subtitle="context.name" @close="close"><div class="context-notice"><Icon name="building"/><span>Empresa: <strong>{{context.name}}</strong></span></div><div v-if="error" class="message error" role="alert">{{error}}</div><form id="finance-form" @submit.prevent="save"><template v-if="mode==='new'"><div class="form-grid"><label>Tipo<select v-model="form.kind"><option value="payable">Conta a pagar</option><option value="receivable">Conta a receber</option></select></label><label>Documento<input v-model="form.document" placeholder="Número ou referência"/></label><label class="span-2">Descrição *<input v-model="form.description" required placeholder="Descrição da obrigação ou recebimento"/></label><label class="span-2">Cliente / fornecedor<input v-model="form.partner_name"/></label><label>Emissão *<DateInput v-model="form.issue_date" required/></label><label>Vencimento *<DateInput v-model="form.due_date" required/></label><label>Valor (R$) *<input v-model="form.amount" inputmode="decimal" required placeholder="0,00"/></label><label>Documento fiscal vinculado<select v-model.number="form.document_id"><option value="">Título avulso</option><option v-for="d in data.documents" :key="d.id" :value="d.id">{{d.number}} · {{d.partner_name}}</option></select></label></div></template><template v-else><div class="settlement-title"><strong>{{selected.description}}</strong><span>Saldo disponível para baixa: <b>{{money(selected.balance_cents)}}</b></span></div><div class="form-grid"><label>Data da baixa *<DateInput v-model="form.date" required/></label><label>Valor da baixa (R$) *<input v-model="form.amount" inputmode="decimal" required/></label><label class="span-2">Histórico / motivo *<input v-model="form.reason" required placeholder="Identifique o pagamento ou recebimento"/></label></div><label class="choice-card"><input type="checkbox" v-model="form.integrate"/><div><strong>Gerar lançamento contábil desta baixa</strong><small>Selecione as duas contas. O período contábil deve estar aberto.</small></div></label><div v-if="form.integrate" class="form-grid"><label>Conta a debitar *<select v-model.number="form.debit_account_id" required><option value="">Selecione</option><option v-for="a in data.accounts.filter(a=>a.analytical)" :key="a.id" :value="a.id">{{a.access_code}} · {{a.name}}</option></select></label><label>Conta a creditar *<select v-model.number="form.credit_account_id" required><option value="">Selecione</option><option v-for="a in data.accounts.filter(a=>a.analytical)" :key="a.id" :value="a.id">{{a.access_code}} · {{a.name}}</option></select></label></div></template></form><template #footer><span class="footer-hint"><Icon name="shield" :size="15"/>Valor, data e responsável ficam registrados.</span><div class="actions"><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="finance-form" type="submit" :disabled="busy"><Icon :name="busy?'loading':'check'"/>{{mode==='new'?'Salvar título':'Confirmar baixa'}}</button></div></template></BaseModal></div></template>
